// Paginación manual por FECHA en vez de por página/cursor -- confirmamos que
// esta cuenta de cal.com no respeta `page`, `skip` ni `cursor` (currentPage
// se quedaba clavado en 1). El único filtro confirmado funcionando es
// `afterStart` (totalItems bajaba correctamente al aplicarlo).
// Estrategia: pedir 100 ordenados por fecha (sortStart=asc), y para la
// siguiente vuelta usar como "cursor" el start más reciente visto + 1ms.
// Se toma el máximo de TODO el batch (no solo el último item) para ser
// robusto por si sortStart no se respeta al 100%.
const apiKey = $('Config').item.json.cal_api_key;
const diasAtras = Number($('Config').item.json.dias_atras) || 400;

let afterStart = new Date(Date.now() - diasAtras * 24 * 60 * 60 * 1000).toISOString();

const allBookings = [];
const limit = 100;
const maxIterations = 100; // tope de seguridad -- se esperan ~22 iteraciones (2158 items / 100)
let iterations = 0;

while (iterations < maxIterations) {
  iterations += 1;

  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.cal.com/v2/bookings',
    qs: { limit, afterStart, sortStart: 'asc' },
    headers: {
      Authorization: `Bearer ${apiKey}`,
      'cal-api-version': '2024-08-13'
    },
    json: true
  });

  const data = response.data || [];
  const pag = response.pagination || {};

  allBookings.push(...data);

  if (data.length === 0) break; // no queda nada más

  // ¿esta respuesta ya cubrió TODO lo que matcheaba el afterStart actual?
  if (pag.totalItems !== undefined && pag.totalItems <= data.length) break;

  let maxStartMs = -Infinity;
  for (const b of data) {
    const t = b.start ? new Date(b.start).getTime() : NaN;
    if (!isNaN(t) && t > maxStartMs) maxStartMs = t;
  }

  if (!isFinite(maxStartMs)) break; // ningún booking con start parseable en este batch

  const nextAfterStart = new Date(maxStartMs + 1).toISOString();
  if (nextAfterStart === afterStart) {
    // salvavidas anti-loop-infinito: el cursor de fecha no avanzó
    return [{
      json: {
        _error: 'PAGINACION_POR_FECHA_NO_AVANZA',
        _detalle: 'El afterStart no avanzó entre iteraciones -- revisar manualmente los bookings devueltos.',
        _bookings_recuperados_hasta_el_corte: allBookings.length
      }
    }];
  }
  afterStart = nextAfterStart;
}

// dedupe por id como red de seguridad ante algún overlap en los bordes
const seen = new Set();
const deduped = [];
for (const b of allBookings) {
  if (b.id !== undefined) {
    if (seen.has(b.id)) continue;
    seen.add(b.id);
  }
  deduped.push(b);
}

return deduped.map(b => ({ json: b }));

// Normaliza cada booking probando varios paths de campo posibles,
// y descarta los que quedan antes del corte de fecha.
// El corte se calcula ACA (no en el nodo Config) para evitar depender de
// que un Set node pueda leer un campo hermano recien calculado en el mismo
// nodo -- eso fue justamente el bug que dejaba cutoff_iso = hoy y descartaba todo.
const diasAtras = Number($('Config').item.json.dias_atras) || 400;
const cutoff = new Date(Date.now() - diasAtras * 24 * 60 * 60 * 1000);

const out = [];

for (const item of $input.all()) {
  const b = item.json || {};

  if (b._error) {
    out.push({ json: b }); // diagnóstico del loop de paginación -- pasa sin tocar
    continue;
  }

  const attendee = Array.isArray(b.attendees) ? b.attendees[0] : (b.attendee || {});
  const bfr = b.bookingFieldsResponses || {};

  const fecha = b.start || b.startTime || b.createdAt || null;
  if (fecha && !isNaN(new Date(fecha)) && new Date(fecha) < cutoff) {
    continue; // fuera de la ventana de recuperación
  }

  const nombre = attendee.name || attendee.fullName || bfr.name || b.title || null;
  const email = attendee.email || bfr.email || b.email || null;

  const telefono = attendee.phoneNumber
    || bfr.attendeePhoneNumber
    || attendee.phone
    || (b.responses && b.responses.phone)
    || b.smsReminderNumber
    || (b.metadata && b.metadata.phone)
    || null;

  out.push({
    json: {
      uid: b.uid || b.id || null,
      nombre,
      email,
      telefono,
      telefono_encontrado: Boolean(telefono),
      fecha,
      estado: b.status || null,
      tipo_servicio: (b.eventType && b.eventType.slug) || (b.eventType && b.eventType.title) || b.title || null,
      raw_keys: Object.keys(b),
      attendee_raw_keys: Object.keys(attendee || {})
    }
  });
}

return out;

// Dedup por teléfono (o email si no hay teléfono), quedándose con el
// booking más reciente de cada cliente — el objetivo es notificar 1 vez
// por persona, no 1 vez por reserva.
const seen = new Map();

for (const item of $input.all()) {
  const c = item.json;
  const key = c.telefono || c.email || c.nombre;
  if (!key) continue;

  const existing = seen.get(key);
  const fechaActual = c.fecha ? new Date(c.fecha).getTime() : 0;
  const fechaExistente = existing && existing.fecha ? new Date(existing.fecha).getTime() : -1;

  if (!existing || fechaActual > fechaExistente) {
    seen.set(key, c);
  }
}

return Array.from(seen.values()).map(c => ({ json: c }));
